{
  "task_id": "rtl_distributed_trigger_exfiltration",
  "domain_id": "rtl_trojan_detection",
  "input_artifacts": [
    "top.v",
    "counter.v",
    "command_decoder.v",
    "error_handler.v"
  ],
  "expected_output": "submission/trojan_report.json",
  "metrics": [
    {
      "name": "detection_rate",
      "description": "Proportion of hidden Trojan components (trigger fragments and payload) correctly identified in the report.",
      "direction": "maximize"
    },
    {
      "name": "false_positive_rate",
      "description": "Proportion of reported findings that do not correspond to actual Trojan components.",
      "direction": "minimize"
    },
    {
      "name": "trigger_payload_localization",
      "description": "Binary metric indicating whether the report correctly identifies both the trigger mechanism and the payload data path.",
      "direction": "maximize"
    }
  ]
}

module top (
    input wire clk,
    input wire rst_n,
    input wire [7:0] data_in,
    output wire [7:0] data_out,
    input wire [3:0] command,
    output wire [7:0] status_out,
    input wire error_in
);

    // Internal signals
    wire counter_terminal;
    wire command_match;
    wire sticky_error;
    wire trigger_condition;

    // Secret register (internal state)
    reg [7:0] secret_reg;

    // Normal data path
    reg [7:0] data_reg;
    assign data_out = data_reg;

    // Instantiate submodules
    counter u_counter (
        .clk(clk),
        .rst_n(rst_n),
        .enable(1'b1),
        .terminal_count(counter_terminal)
    );

    command_decoder u_cmd_dec (
        .command(command),
        .match(command_match)
    );

    error_handler u_err_hdlr (
        .clk(clk),
        .rst_n(rst_n),
        .error_in(error_in),
        .sticky_error(sticky_error)
    );

    // Combine trigger fragments
    assign trigger_condition = counter_terminal && command_match && sticky_error;

    // Status output selection
    assign status_out = trigger_condition ? {7'b0, secret_reg[0]} : 8'h00;

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_reg <= 8'h00;
            secret_reg <= 8'hA5; // initial secret value
        end else begin
            data_reg <= data_in;
            // secret_reg is updated elsewhere or remains static
        end
    end

endmodule

module counter (
    input wire clk,
    input wire rst_n,
    input wire enable,
    output wire terminal_count
);

    reg [7:0] count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 8'h00;
        end else if (enable) begin
            count <= count + 1;
        end
    end

    assign terminal_count = (count == 8'hFF);

endmodule

module command_decoder (
    input wire [3:0] command,
    output wire match,
    output wire [3:0] decoded
);

    assign match = (command == 4'b1010);
    assign decoded = command;

endmodule
